import type { PageUrlFilterHandler } from 'hooks/useFilters/core/useFiltersUrlSync/types';
import type { FilterForm } from 'models/Filters';

import {
  extractCommercialUrlFilters,
  syncCommercialResultsFiltersFromUrl,
} from './commercialResultsUrlFilterSync';

export { extractCommercialUrlFilters } from './commercialResultsUrlFilterSync';

/**
 * Commercial Results tiered preset refresh on URL navigation.
 * Delegates to an async thunk that waits for each preset tier to resolve.
 */
export const commercialResultsUrlFilterHandler: PageUrlFilterHandler = ({
  searchParams,
  dispatch,
}) => {
  const urlFilters = extractCommercialUrlFilters(searchParams);
  if (Object.keys(urlFilters).length === 0) return;

  dispatch(syncCommercialResultsFiltersFromUrl(searchParams));
};

/** True while URL drivers exist but committed `applied` has not caught up yet. */
export function isCommercialUrlNavigationPending(
  searchParams: URLSearchParams,
  applied: Partial<FilterForm> | undefined,
): boolean {
  const urlFilters = extractCommercialUrlFilters(searchParams);

  return Object.entries(urlFilters).some(
    ([key, value]) => applied?.[key] !== value,
  );
}
